"""Render audited source status; snapshots are never presented as current vacancies."""
from pathlib import Path
import json,html,datetime,re
j=json.load(open('data/source-audit.json'));j['commercialStops']=json.load(open('data/commercial-stops.json'))['meta'];j['curbLiveResearch']=json.load(open('data/curb-live-research.json'));Path('data/source-audit.json').write_text(json.dumps(j,ensure_ascii=False,indent=2));f=j['fees'];a=j['roadReference'];l=j['lots'];g=j['roadGeometry'];active=f['activeSource'];fmt=lambda x:f'{x:,}'
checked=datetime.datetime.fromisoformat(j['checkedAt']).astimezone(datetime.timezone(datetime.timedelta(hours=8))).strftime('%Y/%m/%d %H:%M')
try: live_time=datetime.datetime.strptime(l['availabilitySourceTime'],'%a %b %d %H:%M:%S CST %Y').strftime('%Y/%m/%d %H:%M')+'（台灣時間）'
except (ValueError,KeyError): live_time=str(l.get('availabilitySourceTime') or '來源未提供')
body=f'''<a href="/">← 回停車查詢</a><h1>資料完整度與來源</h1><p class="muted">核對時間：{checked}（台灣時間）。以下是收集與一致性稽核快照，不是此刻空位數。</p><section><h2>路邊位置</h2><div class="stats"><div><strong>{fmt(g['accepted'])}</strong>採用車格位置</div><div><strong>1,168</strong>身障專用</div><div><strong>1,764</strong>貨車裝卸</div></div><p>官方全檔 {fmt(g['raw_records'])} 筆；本頁相關候選 72,144 筆；{fmt(g['quarantined'])} 筆因屬性不一致、停車場屬性待核對或重複而隔離。其餘主要是未納入本網站的車種類別，不能算成一般汽車漏收。</p><p>圖層檔名日期 2026/10/02；下載資源更新 2026/10/06；本次重新下載，SHP SHA-256 與先前相同。沒有把今天的核對日期當成圖資更新日期。</p><p><a href="{g['source_url']}" target="_blank" rel="noopener">官方圖資來源</a></p></section>
<section><h2>費率收集與可套用範圍</h2><p>已擷取官方 2026/10/13 產製的計時、計次 PDF 共 <b>2,431 筆</b>，43 頁逐頁檢查筆數一致。文件未標示生效日；產製日期不是費率生效日期。</p><div class="stats"><div><strong>{fmt(active['boundSpaces'])}</strong>新 PDF 範圍配對車格</div><div><strong>{fmt(a['linkedSpaces'])}</strong>官方識別碼費率原文參考</div></div><p>範圍配對還須通過計費條件解析才上色。原文參考以「路段 ID＋格號」唯一配對，並核對完整路名；缺少收費日或計時／計次單位時不換算時薪，身障與專用格不套用一般優惠。</p><p>一般小型車 {fmt(f['passengerCarSpaces'])} 格中，有新 PDF 規則或官方原文參考 {fmt(f['carSpacesWithEitherReference'])} 格（{f['carSpacesWithEitherReference']/f['passengerCarSpaces']:.1%}）；仍缺這兩類參考 {fmt(f['carSpacesWithoutEitherReference'])} 格。這不是全市合法車格涵蓋率。</p><p>舊版 ODS 配對 15,398 格；本次改用新 PDF 後採用 {fmt(active['boundSpaces'])} 格。未能唯一定位或規則衝突者退回灰色，<b>不回退舊價、不為增加數量放寬地理門檻</b>。兩份表有 72 個同名同起訖範圍的規則差異，不能只更新下載日期。</p><p>新 PDF 另有 7 組重複範圍，其中 5 組規則不同。不同計費方案、混合時段、未定位範圍與衝突不自動套價。舊 ODS 於本次重抓仍為 2026/03/27 版本，僅保留供比較。</p><ul>'''
for source in active['sources']:body+=f'<li><a href="{source["url"]}" target="_blank" rel="noopener">官方 { {"hourly":"計時費率 PDF","entry":"計次費率 PDF","symbols":"費率符號說明 PDF"}[source["name"]] }</a></li>'
body+='</ul></section>'
co=l.get('coordinates',{});cc=co.get('counts',{})
if cc:
 body+=f'''<section><h2>已修正：TWD97 停車場漏載</h2><div class="stats"><div><strong>{cc['passengerCarLocatedAfter']:,} / {cc['passengerCarLots']:,}</strong>官方小型車場可定位</div><div><strong>+{cc['passengerCarRestored']:,}</strong>恢復座標與原始費率資料</div></div><p>舊版只讀經緯度，漏掉只有 TW97X／TW97Y 的場址。現在保留可用 WGS84 入口，缺時才將 TWD97（台灣121分帶，EPSG:3826）轉換；小型車場從 {cc['passengerCarLocatedBefore']:,} 處增至 {cc['passengerCarLocatedAfter']:,} 處。全檔 {cc['allRecords']:,} 筆均可解析位置，並以獨立 PROJ 轉換核對。轉換點是官方場址，不保證為可駛入入口。</p><p>補回的 {cc['passengerCarRestored']:,} 場在本次餘位快照中，{cc['restoredWithLiveRecord']:,} 場有紀錄、{cc['restoredWithNonnegativeCarValue']:,} 場有非負小型車數值、{cc['restoredWithPositiveCarValue']:,} 場大於零。這是 {html.escape(live_time)} 的來源場數，不是現在空位。查詢仍檢查時間、營業狀態與車種。</p><p>卡片詳細資料亦保留身障優惠、孕婦／育兒、充電與無障礙設施原始欄位；不將設施總數當作可用數，未推定特殊資格優惠。</p><p><a href="https://www-ws.gov.taipei/001/Upload/public/mmo/dot/%E5%81%9C%E8%BB%8A%E8%B3%87%E8%A8%8A%E5%B0%8E%E5%BC%95%E7%B3%BB%E7%B5%B1%E8%B3%87%E6%96%99%E5%BA%AB%E4%BB%8B%E6%8E%A5%E8%AA%AA%E6%98%8E%E6%96%87%E4%BB%B6.pdf#page=7">官方座標欄位說明</a> · <a href="https://schema.gov.tw/en/high-value/6">政府座標參考標準</a></p></section>'''
c=j.get('commercialStops')
if c:
 body+=f'''<section><h2>新增：共用臨停區用途參考</h2><p>採用官方 {c['sourceUpdated'][:10]} 更新的 CSV：原始 {c['records']} 列、{c['spaces']} 格。{c['quarantinedRecords']} 列有重複座標、異址同點或距同名道路車格過遠，保守隔離，留下 <b>{c['acceptedRecords']} 處公告位置參考</b>（表列 {c['acceptedSpaces']} 格，非空位）。位置未經逐點現地驗證，且可能與既有裝卸格重疊，<b>不加進 {g['accepted']:,} 車格總數</b>。</p><p>在「貨車／裝卸」篩選顯示，清楚標「共用臨停」。限20分鐘，貨車須行照標示貨車且實際裝卸，客貨兩用車不可使用。亦供符合公告的計程車、復康巴士、長照／福祉車、到宅沐浴車上下客貨；一般小客車不適用。逐點牌面、費率與空位未提供，不推定免費。</p><p><a href="{c['dataset']}">官方位置資料</a> · <a href="{c['rulesSource']}">最新資格與20分鐘規則</a></p></section>'''
r=j.get('curbLiveResearch')
if r:
 body+=f'''<section><h2>逐格即時：正式來源已確認，尚未啟用</h2><p>TDX 正式接口已確認包含臺北市逐格基本資料、動態及收費時段。官方資料集標示每1分鐘更新，動態提供格位碼、設備狀態與逐格資料時間。<b>需正式 API Key，尚未取得有授權的全量資料</b>，有效格數、配對率與新鮮度仍未驗證。</p><p>北市官方網站可呈現逐格狀態，不代表網站內部接口可直接拿來介接。此版保留路邊空位未知；完成正式存取、唯一格位對應、時間語意、設備與禁停規則驗證後才可啟用，不能拿抓取時間取代逐格時間。</p><p><a href="{r['source']}">TDX 官方動態資料集與授權要求</a> · <a href="{r['specification']}">正式 API 欄位說明</a></p></section>'''

body+=f'''<section><h2>停車場與即時資料</h2><p>此次官方基本資料 <b>{l['inventoryRecords']:,}</b> 處（其中有小型車容量 {l['passengerCarLots']:,} 處、有身障容量 {l['accessibleLots']:,} 處）；全部有收費文字，文字不一定可換算單一時薪。</p><p>餘位檔有 <b>{l['liveRecords']:,}</b> 處能配對基本資料，另有 <b>{l['inventoryWithoutLiveRecord']:,}</b> 處沒有餘位紀錄。有非負小型車餘位值 {l['nonnegativeCarAvailability']:,} 處，有非負身障餘位值 {l['nonnegativeAccessibleAvailability']:,} 處；這些是提供數值的場數，不是空位總數。</p><p>檔案來源時間：{html.escape(live_time)}。實際查詢每次另外讀取，逾 10 分鐘或負數不當作有效空位。</p><p><a href="{l['source']}">官方基本資料 XML</a> · <a href="{l['liveSource']}">官方餘位 XML</a></p></section>
<section><h2>仍未補齊的關鍵缺口</h2><ul><li>路邊即時檔 {a['cells']:,} 個 cell 中僅 {a['nonzeroCoordinateCells']} 個有非零座標，且這 3 個沒有更新時間。新識別碼連結只補費率參考，沒有啟用空位狀態。</li><li>逐格即時狀態代碼、資料新鮮度及同一格的語意尚未充分驗證，路邊一律顯示空位未知。</li><li>新 PDF 的 {active['carRows']-active['scopedRows']:,} 筆尚無完全對應的既有道路起訖幾何，不能只靠同一路名套價。</li><li>臨時交通管制、現場用途與資格、私人停車場即時回報缺漏仍須依官方與現場確認。</li></ul><a href="{a['dataset']}">官方路邊資料說明</a></section>
<section><h2>各區採用的位置資料</h2><div class="table-wrap"><table><thead><tr><th>行政區</th><th>全部</th><th>一般小型</th><th>身障</th><th>裝卸</th><th>PDF 配對</th><th>官方原文</th></tr></thead><tbody>'''
for d in j['districts']:body+='<tr>'+''.join('<td>'+html.escape(str(d[k]))+'</td>' for k in ['district','accepted','passengerCar','accessible','freight','feeRuleBound','officialReferenceLinked'])+'</tr>'
body+='</tbody></table></div><p class="muted">兩種費率欄位會重疊，不可相加。全部含共用、限時等其他支援類別；13 格的行政區欄位空白，不自行猜填。</p></section><section><h2>可重現稽核</h2><p>保留來源網址、雜湊、資料日期與擷取方式，可查看 <a href="/api/data-coverage">完整 JSON 稽核資料</a>。本頁是發布時快照，不會因按「更新空位」而自動重新擷取圖資／PDF。</p></section><footer>TaipeiPark · 非政府官方網站。以現場標誌及主管機關公告為準。</footer>'
page='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TaipeiPark｜資料完整度與來源</title><style>body{margin:0;background:#0c1725;color:#e6edf7;font:16px/1.65 system-ui,sans-serif}main{max-width:920px;margin:auto;padding:24px 18px 60px}h1{font-size:28px;margin:18px 0 8px}h2{font-size:21px}a{color:#9ad4ff}section{background:#162437;border:1px solid #304158;border-radius:16px;padding:20px;margin:20px 0}p{overflow-wrap:anywhere}.muted,footer{color:#a8b9ce;font-size:14px}.stats{display:flex;gap:12px;flex-wrap:wrap}.stats>div{flex:1;min-width:130px;background:#20364d;border-radius:12px;padding:14px}.stats strong{display:block;font-size:28px;color:#aee8d2}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;text-align:right}th,td{padding:8px;border-bottom:1px solid #33465e}th:first-child,td:first-child{text-align:left}li{margin:8px 0}@media(max-width:480px){section{padding:16px}main{padding:20px 12px}h1{font-size:25px}.stats strong{font-size:24px}}</style><main>'''+body+'</main></html>'
Path('taipei_parking_mobile/data-coverage.html').write_text(page)
# Keep source/coverage details behind the existing info icon.
p=Path('taipei_parking_mobile/index.html');h=p.read_text()
block=f'''<details id="road-fee-info"><summary>路邊費率來源與更新時間</summary><p>現用官方計時／計次 PDF 產製：2026/10/13；生效日期未提供。本次取得整理：{checked}（台灣時間）。舊 2026/03/27 ODS 不再作未匹配項目的價格備援。</p><p>2,431 筆費率；{active['scopedRows']:,} 筆可對應既有道路起訖；{active['boundSpaces']:,} 格範圍配對。另有 {a['linkedSpaces']:,} 格透過官方路段 ID＋格號＋完整路名核對，提供費率原文參考。兩者可重疊；不代表都能上色。</p><p>位置與完整範圍／條件明確者才套價；衝突、專用格與缺日別／單位維持待確認。XML 原文時段不代表禁停規則。此為固定快照，不隨每分鐘餘位更新。</p><p><a href="{active['source']}" target="_blank" rel="noopener">官方費率 PDF 與符號說明 ↗</a> · <a href="/data-coverage">資料完整度、各區覆蓋與缺口 ↗</a></p></details>'''
h=re.sub(r'<details id="road-fee-info">[\s\S]*?</details>',lambda _:block,h)
if 'id="lot-source-status"' not in h:h=h.replace('<details class="info-fold"><summary>假日日曆', '<details class="info-fold"><summary>停車場來源覆蓋與新鮮度</summary><p id="lot-source-status" aria-live="polite">等待本次官方資料查詢。</p><p>來源沒有回報或資料過期不代表沒有車格。<a href="/data-coverage">查看全量來源檢查與缺漏</a></p></details><details class="info-fold"><summary>假日日曆')
h=h.replace('檢查日期：2026/10/27。官方圖層檔名日期：2026/10/02。','原檔檢查：2026/10/27；2026/11/09 重抓雜湊一致。官方圖層檔名日期：2026/10/02。')
p.write_text(h)
print('Rendered coverage page and info panel')
